data_dict:
{'dcid': {'column_description': 'Unique Identifier for the child Care programs.', 'expected_per_allowed_values': 'Text', 'additional_notes': "Always starts with 'DC' followed by a number."}, 'permit_number': {'column_description': 'Permit number for a group child care program. ', 'expected_per_allowed_values': 'Text', 'field_limitations': 'School-based child care programs are not assigned a permit number so the value is "N/A". ', 'additional_notes': 'DCID is the unique identifier for school-based child care programs. '}, 'program_name': {'column_description': 'Name of the child care program.', 'expected_per_allowed_values': 'Text'}, 'facility_type': {'column_description': 'Describes whether the program is a group child care (GCC), or a School Based Child Care (SBCC), regulated under NYC Health Code Article 43.', 'expected_per_allowed_values': 'Text:  GCC, SBCC
', 'additional_notes': 'A GCC program provides child care to three or more children under 6 years of age. These programs operate for five or more hours per week, for more than 30 days in a 12-month period. They primarily operate in non-residential spaces. 

A SBCC program provides instruction to children ages 3 through 5 who are located within a school or are part of a school. See child care glossary for further information: https://a816-healthpsi.nyc.gov/ChildCare/glossary  '}, 'program_type': {'column_description': 'Program Type based on age of accepted attendees', 'expected_per_allowed_values': 'Text: INFANT TODDLER; PRESCHOOL', 'additional_notes': 'INFANT TODDLER indicates enrollment prior to two years of age; can remain in program until third birthday. PRESCHOOL indicates enrollment from two years of age; can remain in program until sixth birthday. See child care glossary for further information: https://a816-healthpsi.nyc.gov/ChildCare/glossary'}, 'address': {'column_description': 'Buiding and street address for the child care program', 'expected_per_allowed_values': 'Text'}, 'borough': {'column_description': 'Borough the program is located in', 'expected_per_allowed_values': 'Text: BRONX, BROOKLYN, MANHATTAN, QUEENS, STATEN ISLAND'}, 'zipcode': {'column_description': 'U.S. Postal ZIP code of the program', 'expected_per_allowed_values': 'Text'}, 'phone': {'column_description': 'Phone Number', 'expected_per_allowed_values': 'Text', 'field_limitations': '(xxx) xxx-xxxx'}, 'age_range': {'column_description': 'This field represents the possible age range of children enrolled in the program.', 'expected_per_allowed_values': 'Text', 'field_limitations': 'Due to an error in the data collection system, the age ranges of some programs have not been captured. These values are listed as "NO DATA".', 'additional_notes': "This field shows the allowable ages for children to enroll in the program, but does NOT represent the children's actual ages."}, 'administer_medication': {'column_description': 'Indicates whether a program has staff qualified to administer medication.', 'expected_per_allowed_values': 'Text: YES; NO'}, 'bin': {'column_description': 'Department of Buildings (DOB) Building Identification Number', 'expected_per_allowed_values': '7-character text', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'Building Identification Number (BIN) is a seven-digit numerical identifier unique to each building in the City of New York. The first digit is the Borough Code. If the borough code is followed by all zeroes (commonly referred to as a ‘million BIN’, this indicates that a BIN has not been assigned, either because the address associated with the building has not yet been built, an address is assigned as a potential valid range where there is no building (vacant lot or vacant street frontage), or it is associated with a constituent entity of a Complex NAP (Non-Addressable Placename) but does not indicate a building or structure that would have a BIN assignment (such as the Children’s Zoo Spider Web within Central Park). '}, 'bbl': {'column_description': 'Borough Block Lot', 'expected_per_allowed_values': '10-character text', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'Identifies a parcel of real property in New York City, called a tax lot. The BBL contains a 1 byte Borough Code, a 5-byte Tax Block, and a 4-byte tax lot. The tax block and tax lot are both right justified, zero filled. '}, 'community_board': {'column_description': 'Community Board of the location of the building', 'expected_per_allowed_values': '3-character text', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'The first byte is a borough code and the second and third bytes are the community board number. There are 59 community districts in the city of New York, as well as 12 Joint Interest Areas (JIAs). The JIAs are major parks and airports that are not contained within any community districts.'}, 'council_district': {'column_description': 'Council District of the location of the building ', 'expected_per_allowed_values': '2-character text', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'A district represented by a member of the New York City Council. Consists of an aggregation of Election Districts.'}, 'census_tract': {'column_description': 'The 2020 Census Tract of the location of the building', 'expected_per_allowed_values': '6-character text', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'Small, relatively permanent statistical subdivisions of a geographical area as defined by the U.S. Census Bureau. (GEOID2020)'}, 'nta_code': {'column_description': 'NTA (Neighborhood Tabulation Area) code of the location of the building', 'expected_per_allowed_values': '6 character code', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'Unique identifier for each Neighborhood Tabulation Area (NTA). Includes 6 characters: 2 alpha for borough, 2 numeric matching CDTA number, 1 numeric indicating NTA Type, and 1 numeric to create unique ID. NTAs were created by the Department of City Planning to project populations at a small area level for PlaNYC, the long-term sustainability plan for New York City. These are now being used to present data from the Decennial Census and American Community Survey. (2020 NTA)'}, 'latitude': {'column_description': 'Latitude of the location of the building', 'expected_per_allowed_values': 'Number', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'Lines of latitude measure the north-south position between the poles with the equator defined as 0 degrees. The units of measure are degrees and minutes.'}, 'longitude': {'column_description': 'Longitude of the location of the building ', 'expected_per_allowed_values': 'Number', 'field_limitations': 'Provided by geocoding services', 'additional_notes': 'Lines of longitude (or meridians) measure the east-west position, with the prime meridian running through Greenwich, England. The units of measure are degrees and minutes.'}}
